// Общие шаги: полоса «חפש עסק · חיפוש וסינון ממוקד» под мобильной шапкой (#1a3a08), «פרסם עסק» в шапке и
// блок «עסקים נוספים שעשויים לעניין אותך» после результатов /search (#839121).
// Прод, только просмотр: не-GET запросы обрываются (для вошедшего пропускается только обновление входа /auth/v1/),
// cookie — «только необходимые» (до загрузки), service worker блокируется в spec (test.use).
import { expect, BrowserContext, Page } from '@playwright/test';

export const LOAD = { timeout: 30_000 };
export const CATEGORY = 'בית מלון';
export const QUERY = 'מסעדה';
export const MORE_TITLE = 'עסקים נוספים שעשויים לעניין אותך';
const SAFE_METHODS = ['GET', 'HEAD', 'OPTIONS'];

/** Вызывать до первого перехода. keepAuth — не обрывать обновление сессии (вошедший пользователь). */
export async function prepareReadOnly(context: BrowserContext, keepAuth = false) {
  await context.route('**/*', (route) => {
    const req = route.request();
    if (SAFE_METHODS.includes(req.method()) || (keepAuth && req.url().includes('/auth/v1/'))) return route.fallback();
    return route.abort('blockedbyclient');
  });
  await context.addInitScript(() => {
    try {
      if (!localStorage.getItem('cookie-consent-v2')) {
        localStorage.setItem(
          'cookie-consent-v2',
          JSON.stringify({ essential: true, performance: false, marketing: false, updatedAt: new Date().toISOString() }),
        );
      }
    } catch {}
  });
}

export const categoryUrl = (c = CATEGORY) => `/search?category=${encodeURIComponent(c)}`;
export const queryUrl = (q = QUERY) => `/search?q=${encodeURIComponent(q)}`;

/** Полоса под шапкой — кнопка «חפש עסק» с подписью «חיפוש וסינון ממוקד». */
export const strip = (page: Page) => page.getByRole('button', { name: /חפש עסק\s*חיפוש וסינון ממוקד/ });

/** Окно поиска и фильтров, которое открывает полоса. */
export const filterDialog = (page: Page) =>
  page.getByRole('dialog').filter({ has: page.getByRole('heading', { name: 'חיפוש וסינון' }) });

export const publishLink = (page: Page) => page.locator('header').getByRole('link', { name: 'פרסם עסק' });

/** Открыть страницу результатов и дождаться «נמצאו N עסקים». */
export async function openResults(page: Page, url: string) {
  await page.goto(url);
  await expect(page.getByText(/נמצאו \d+ עסקים/).first()).toBeVisible(LOAD);
}

/** Открыть главную и дождаться карточек объявлений. */
export async function openHome(page: Page) {
  await page.goto('/');
  await expect(page.locator('a[href*="businessdetail"]').first()).toBeAttached(LOAD);
}

/** Прокрутить ниже блока поиска. */
export async function scrollDown(page: Page, y = 1600) {
  await page.evaluate((to) => window.scrollTo(0, to), y);
  await expect.poll(() => page.evaluate(() => window.scrollY)).toBeGreaterThan(y / 2);
}

/** Вверху — полосы нет; после прокрутки — видна; нажатие открывает окно «חיפוש וסינון» с фильтрами, полоса скрывается. */
export async function stripOpensFilters(page: Page) {
  await expect(strip(page), 'вверху страницы полосы «חפש עסק» нет').toBeHidden();
  await scrollDown(page);
  await expect(strip(page), 'после прокрутки полоса «חפש עסק» видна').toBeVisible();
  const box = await strip(page).boundingBox();
  const header = await page.locator('header').boundingBox();
  expect(box && header && box.y >= header.y + header.height - 2, 'полоса — под шапкой').toBeTruthy();

  await strip(page).click();
  const dialog = filterDialog(page);
  await expect(dialog, 'нажатие открывает окно «חיפוש וסינון»').toBeVisible();
  for (const label of ['אזור', 'עיר', 'סוג מודעה', 'קטגוריה', 'סוג מכירה'])
    await expect(dialog.getByText(label, { exact: true }), `фильтр «${label}» в окне`).toBeVisible();
  await expect(dialog.getByText('טווח מחירים'), 'фильтр цены в окне').toBeVisible();
  await expect(dialog.getByRole('button', { name: 'סנן תוצאות' })).toBeVisible();
  await expect(strip(page), 'при открытом окне полоса скрыта').toBeHidden();
  return dialog;
}

/** id объявлений по ссылкам businessdetail (без повторов). more=true — только карточки блока «עסקים נוספים». */
export async function listingIds(page: Page, more: boolean): Promise<string[]> {
  const sel = more
    ? 'a[href*="businessdetail"][href*="source=search_more_listings"]'
    : 'a[href*="businessdetail"]:not([href*="source=search_more_listings"])';
  const ids = await page
    .locator(sel)
    .evaluateAll((as) => as.map((a) => new URL((a as HTMLAnchorElement).href).searchParams.get('id') || ''));
  return [...new Set(ids.filter(Boolean))];
}

/** Дождаться блока «עסקים נוספים» с карточками. */
export async function waitMoreBlock(page: Page) {
  const heading = page.getByRole('heading', { name: MORE_TITLE });
  await expect(heading, `блок «${MORE_TITLE}» есть`).toBeAttached(LOAD);
  await heading.scrollIntoViewIfNeeded();
  await expect(heading).toBeVisible();
  await expect
    .poll(async () => (await listingIds(page, true)).length, { ...LOAD, message: 'в блоке есть карточки' })
    .toBeGreaterThan(0);
}
